\header {
  title = "寅时清肃·商音润肺"
  composer = "中医五音养生系统"
  tagline = ##f
}

global = {
  \key f \major  % 商调式主音F（手太阴肺经）
  \time 12/8     % 复合拍型：4+3+5
}

% 编钟声部（商调式《阳春白雪》变奏）
bell = \relative c'' {
  \global
  \clef "treble"
  \tempo "Maestoso" 4.=60
  f8\p(\< e d c b a)\! | d(\> f a b d f)\! |
  % 金石泛音链（256-512Hz）
  g4.\mp( f8 e d) | b( d g a b d) |
  \override Glissando.style = #'trill
  e8\mf( d b a \glissando g f) | d( e f g a b) |
  \tuplet 4/3 { d16( e f g } a8) r4. | g2.\fermata
}

% 古琴声部（《阳关三叠》微分音重构）
guqin = \relative c' {
  \global
  \clef "alto"
  f8\p( g a b c d) | e( d c b a g) |
  % 模拟肺经气血流动
  f4.(\mp g8 a b) | c( b a g f e) |
  \tuplet 5/3 { f8( g a b c } d e f) | a\f( g f e d c) | b2.\fermata
}

% 自然声效部（晨鸟声景）
birds = \drummode {
  \global
  \repeat unfold 2 {
    tomh4.\ppp r8 tomh4 | 
    % 生物节律脉冲模型（3-8kHz）
    \tuplet 4/3 { tomh8 tomh tomh tomh } \tuplet 3/3 { toml toml toml } |
    \tuplet 5/2 { tomh8 tomh tomh tomh tomh } 
  }
}

\score {
  <<
    \new Staff \with { instrumentName = "青铜编钟" } \bell
    \new Staff \with { instrumentName = "古琴" } \guqin
    \new DrumStaff \with { instrumentName = "晨鸟声景" } \birds
  >>
  \layout {
    \context {
      \Score
      \override SpacingSpanner.base-shortest-duration = #(ly:make-moment 1/24)
    }
  }
}

